<?php
/** Nexa Security — login brute-force guard + audit log (SQL query()). */
function nexa_security_ensure(): void { if(!table_exists('login_attempts')) create_table('login_attempts',['ip','username','attempts','last_attempt','blocked_until']); if(!table_exists('audit_log')) create_table('audit_log',['actor','action','details','ip','created_at']); }
nexa_security_ensure();
function nexa_security_ip(): string { return (string)($_SERVER['REMOTE_ADDR']??'127.0.0.1'); }
function nexa_security_blocked(string $ip): bool { nexa_security_ensure(); $r=query("SELECT blocked_until FROM login_attempts WHERE ip=?",[$ip]); return !empty($r) && (int)($r[0]['blocked_until']??0)>time(); }
function nexa_security_audit(string $action, string $details=''): void { nexa_security_ensure(); query("INSERT INTO audit_log (actor,action,details,ip,created_at) VALUES (?,?,?,?,?)", [$_SESSION['name']??'guest',$action,mb_substr($details,0,250),nexa_security_ip(),date('Y-m-d H:i:s')]); }
add_action('nexa_login_failed', function($user){ nexa_security_ensure(); $ip=nexa_security_ip(); $max=max(2,(int)get_setting('security_max_attempts','5')); $lock=max(60,(int)get_setting('security_lock_seconds','900')); $r=query("SELECT * FROM login_attempts WHERE ip=?",[$ip]); if(empty($r)) query("INSERT INTO login_attempts (ip,username,attempts,last_attempt,blocked_until) VALUES (?,?,?,?,?)",[$ip,(string)$user,1,time(),0]); else { $n=(int)$r[0]['attempts']+1; query("UPDATE login_attempts SET attempts=?, username=?, last_attempt=?, blocked_until=? WHERE ip=?", [$n,(string)$user,time(), ($n>=$max?time()+$lock:($r[0]['blocked_until']??0)), $ip]); } nexa_security_audit('login_failed',(string)$user); });
add_action('nexa_login_succeeded', function($user){ nexa_security_ensure(); query("DELETE FROM login_attempts WHERE ip=?",[nexa_security_ip()]); nexa_security_audit('login_succeeded',(string)$user); });
add_action('post_saved', function($id){ nexa_security_audit('post_saved','post #'.$id); });
function nexa_security_guard(): void { $script=basename((string)($_SERVER['SCRIPT_NAME']??'')); if(in_array($script,['login.php','authenticate.php'],true) && nexa_security_blocked(nexa_security_ip())) { http_response_code(429); echo '<h2>Too many failed login attempts.</h2><p>Your IP is temporarily blocked. Please try again later or ask an admin to unblock you in Admin &rarr; Security.</p>'; exit; } }
